-- Preview password protection (#107, design doc §5.1). Keep in sync with
-- migrations/postgres/0009_site_preview_protection.sql.
--
-- When preview_protection is on, Traefik asks for HTTP basic auth on the
-- site's preview domain. The password is generated by the platform and
-- stored encrypted as a secret (preview_password_secret_ref), so it can be
-- sent by uptime checks; the API shows it only once. Traefik gets only its
-- bcrypt hash (preview_password_hash), kept here so that re-rendering the
-- site produces the same labels instead of a new salt, and a new container,
-- every time. The password and hash stay when protection is turned off, so
-- turning it on again restores the same credentials.
ALTER TABLE sites ADD COLUMN preview_protection BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE sites ADD COLUMN preview_username TEXT NOT NULL DEFAULT '';
ALTER TABLE sites ADD COLUMN preview_password_hash TEXT NOT NULL DEFAULT '';
ALTER TABLE sites ADD COLUMN preview_password_secret_ref TEXT NOT NULL DEFAULT '';
